import {newGuidedRepair,guidedHint,chooseGuidedRepair,nextGuidedRepair,guidedScore} from './workshop-repair-guided.mjs';
import {newRepair,causes} from './workshop-repair-model.mjs';
import {required,faultModes} from './workshop-model.mjs';
export const guidedHistoryKey='mecanica.workshop.guidedRepairHistory.v1',guidedDraftKey='mecanica.workshop.guidedRepairDraft.v1';
export function restoreGuided(data){try{if(!data||typeof data.id!=='string'||typeof data.key!=='string'||!Object.hasOwn(required,data.user?.kind)||!faultModes.includes(data.user.fault)||!Array.isArray(data.rounds)||data.rounds.length>1000)return null;const g=newGuidedRepair({repair:newRepair(data.user)}),needed=causes(data.user);if(!Array.isArray(data.order)||data.order.length!==needed.length||new Set(data.order).size!==needed.length||!data.order.every(id=>needed.includes(id)))return null;g.order=[...data.order];for(const [i,r]of data.rounds.entries()){if(r.hint)guidedHint(g);if(!chooseGuidedRepair(g,r.id))return null;const actual=g.rounds.at(-1);if(actual.useful!==r.useful||actual.recommended!==r.recommended)return null;if(i<data.rounds.length-1||data.phase!=='feedback')nextGuidedRepair(g);}if(data.phase==='question'&&data.hinted)guidedHint(g);if(g.phase!==data.phase||g.hints!==data.hints)return null;return {...g,id:data.id,key:data.key,started:data.started,finished:data.finished,focus:data.focus,source:data.source,plan:data.plan,context:data.context};}catch{return null;}}
export function loadGuidedHistory(storage){const data=JSON.parse(storage.getItem(guidedHistoryKey)||'[]');return Array.isArray(data)?data.map(restoreGuided).filter(g=>g?.phase==='complete'&&Number.isFinite(Date.parse(g.finished))).filter((g,i,a)=>a.findIndex(x=>x.id===g.id)===i).sort((a,b)=>Date.parse(a.finished)-Date.parse(b.finished)).slice(-100):[];}
export function saveGuided(storage,g){if(!restoreGuided(g))throw Error('Invalid guided state');storage.setItem(guidedDraftKey,JSON.stringify(g));if(g.phase==='complete'){g.finished ||=new Date().toISOString();const rows=loadGuidedHistory(storage);if(!rows.some(x=>x.id===g.id))storage.setItem(guidedHistoryKey,JSON.stringify([...rows,g].slice(-100)));storage.setItem(guidedDraftKey,JSON.stringify(g));}}
export function guidedWeaknesses(rows){const groups=new Map();for(const g of rows)for(const r of g.rounds){const key=g.user.kind+':'+r.id;if(!groups.has(key))groups.set(key,{key,kind:g.user.kind,id:r.id,total:0,wrong:0,hints:0,fault:g.user.fault});const group=groups.get(key);group.total++;group.wrong+=Number(!r.useful);group.hints+=Number(r.hint);if(!r.useful)group.fault=g.user.fault;}return [...groups.values()].sort((a,b)=>b.wrong-a.wrong||b.wrong/b.total-a.wrong/a.total||a.key.localeCompare(b.key));}
export const guidedResultScore=guidedScore;
